// QueryAccounts queries the accounts edge of a Fund.
func (c *FundClient) QueryAccounts(_m *Fund) *UnitAccountQuery {
	query := (&UnitAccountClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(fund.Table, fund.FieldID, id),
			sqlgraph.To(unitaccount.Table, unitaccount.FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, fund.AccountsTable, fund.AccountsColumn),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

